// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 100 ether);
        vm.warp(1);

        // First play: random will be 0 (block.timestamp=1, block.difficulty=0, alice)
        vm.prank(alice);
        c.play{value: 10}();

        // After first win, pot should be 0 in reference, but buggy retains 10-1=9
        // So second play adds another 10, making reference pot = 10, buggy pot = 19
        vm.warp(2);
        vm.prank(alice);
        c.play{value: 10}();

        // After second win, reference resets pot to 0, buggy keeps pot = (9+10) = 19 (not reset)
        uint256 potAfter = c.pot();
        assertTrue(potAfter < 19); 
    }
}

