        // block.timestamp = 1, block.difficulty = 1, and msg.sender = address(1) => keccak256(abi.encodePacked(1,1,address(1))) % 2 => 0
        vm.warp(1);
        vm.roll(1);
        address player = address(1);
        vm.deal(player, 100 ether);
